-- Gwanak initial seed data (derived from orda_10_19.sql)
-- Requires the Flyway-managed schema and the source_dataset code-constraint migration.
-- Audit columns are intentionally omitted.
BEGIN;










-- Keep BIGSERIAL sequences aligned with imported primary keys.
SELECT setval(pg_get_serial_sequence('public.app_user', 'user_id'), COALESCE((SELECT MAX(user_id) FROM public.app_user), 1), EXISTS (SELECT 1 FROM public.app_user));
SELECT setval(pg_get_serial_sequence('public.mountain', 'mountain_id'), COALESCE((SELECT MAX(mountain_id) FROM public.mountain), 1), EXISTS (SELECT 1 FROM public.mountain));
SELECT setval(pg_get_serial_sequence('public.source_dataset', 'dataset_id'), COALESCE((SELECT MAX(dataset_id) FROM public.source_dataset), 1), EXISTS (SELECT 1 FROM public.source_dataset));
SELECT setval(pg_get_serial_sequence('public.service_area', 'area_id'), COALESCE((SELECT MAX(area_id) FROM public.service_area), 1), EXISTS (SELECT 1 FROM public.service_area));
SELECT setval(pg_get_serial_sequence('public.course', 'course_id'), COALESCE((SELECT MAX(course_id) FROM public.course), 1), EXISTS (SELECT 1 FROM public.course));
SELECT setval(pg_get_serial_sequence('public.dem_asset', 'dem_id'), COALESCE((SELECT MAX(dem_id) FROM public.dem_asset), 1), EXISTS (SELECT 1 FROM public.dem_asset));
SELECT setval(pg_get_serial_sequence('public.raw_trail', 'raw_trail_id'), COALESCE((SELECT MAX(raw_trail_id) FROM public.raw_trail), 1), EXISTS (SELECT 1 FROM public.raw_trail));
SELECT setval(pg_get_serial_sequence('public.facility', 'facility_id'), COALESCE((SELECT MAX(facility_id) FROM public.facility), 1), EXISTS (SELECT 1 FROM public.facility));
SELECT setval(pg_get_serial_sequence('public.trail_spot', 'spot_id'), COALESCE((SELECT MAX(spot_id) FROM public.trail_spot), 1), EXISTS (SELECT 1 FROM public.trail_spot));

COMMIT;
